import {makeSidewall,traceSidewall,evaluateSidewall} from './sidewall.mjs?v=surround-1';
const check=(d,w=300,n=25)=>{const sim=traceSidewall(d,w,n),quality=evaluateSidewall(d,sim);return{d,sim,quality};};
const better=(a,b)=>!b||(a.quality.accepted&&!b.quality.accepted)||(a.quality.accepted===b.quality.accepted&&a.quality.score>b.quality.score);
self.onmessage=async({data})=>{try{if(data.mode==='search'){const s=data.settings,ys=[...new Set([s.imageY,Math.max(0,s.imageY-30),Math.min(400,s.imageY+30)])],bs=[...new Set([s.bodySide,Math.min(210,s.bodySide+20)])],entries=[];let checked=0,errors=0,nominal;for(const imageY of ys)for(const bodySide of bs){self.postMessage({phase:'progress',label:`Боковые стенки: вариант ${checked+1} из ${ys.length*bs.length}`});try{const d=makeSidewall(data.gray,data.iw,data.ih,{...s,imageY,bodySide}),r=check(d,180,9),e={d,quality:r.quality};entries.push(e);if(imageY===s.imageY&&bodySide===s.bodySide)nominal=e;}catch(e){errors++;}checked++;await new Promise(r=>setTimeout(r,0));}entries.sort((a,b)=>better(a,b)?-1:better(b,a)?1:0);const finalists=entries.slice(0,2);if(nominal&&!finalists.includes(nominal))finalists.push(nominal);if(!finalists.length)throw Error('Нет допустимой боковой конструкции с этими размерами.');let best;for(let i=0;i<finalists.length;i++){self.postMessage({phase:'progress',label:`Точная трассировка стенок: финалист ${i+1} из ${finalists.length}`});const r=check(finalists[i].d,720,25);if(better(r,best))best=r;await new Promise(r=>setTimeout(r,0));}self.postMessage({phase:'done',...best,search:{checked,errors,finalChecks:finalists.length,globalOptimum:false}},[best.sim.data.buffer,best.sim.incident.buffer,best.sim.visibility.buffer]);return;}self.postMessage({phase:'progress',label:'Строим четыре боковые стенки с фигурными вырезами…'});const d=makeSidewall(data.gray,data.iw,data.ih,data.settings);self.postMessage({phase:'progress',label:'Считаем тень по геометрии стенок и крепления…'});const r=check(d,720,25);self.postMessage({phase:'done',...r},[r.sim.data.buffer,r.sim.incident.buffer,r.sim.visibility.buffer]);}catch(e){self.postMessage({phase:'error',message:e.message});}};
